    mahjong_kw("read-nmjl-card.html", "How to Read the NMJL Card", "How to read the NMJL card — understand American mah jongg hands.", "read nmjl card, how to read mah jongg card", "How to Read the NMJL Card", "<p>Learn to <strong>read the NMJL card</strong> — colors, numbers, and hand categories. We teach hands-on in <a href=\"mahjong-101.html\">Mahjong 101</a> · <a href=\"nmjl-card.html\">NMJL guide</a>.</p>", priority="0.87"),
    mahjong_kw("mahjong-suits.html", "Suits — Bams, Cracks & Dots", "Mahjong suits explained — bams, cracks, dots, winds, and dragons.", "mahjong suits, bams cracks dots, mah jongg suits", "Mahjong Suits", "<p>Three suits — <strong>bams, cracks, and dots</strong> — plus winds, dragons, flowers, and jokers. Full breakdown in <a href=\"mahjong-vocabulary.html\">vocabulary</a> · <a href=\"mahjong-101.html\">101</a>.</p>"),
    mahjong_kw("mahjong-dragons.html", "Dragons", "Mahjong dragons explained — red, green, and white dragon tiles.", "mahjong dragons, dragon tiles mah jongg", "Mahjong Dragons", "<p><strong>Dragon tiles</strong> — red, green, and soap (white) — are honor tiles in American mahjong. Learn all tiles in <a href=\"mahjong-101.html\">Mahjong 101</a>.</p>"),
    mahjong_kw("mahjong-winds.html", "Winds", "Mahjong winds explained — east, south, west, north tiles.", "mahjong winds, wind tiles mah jongg", "Mahjong Winds", "<p>Four <strong>wind tiles</strong> — east, south, west, north — used in many NMJL hands. <a href=\"mahjong-vocabulary.html\">Vocabulary</a> · <a href=\"mahjong-101.html\">101</a>.</p>"),
    mahjong_kw("is-mahjong-hard.html", "Is Mahjong Hard?", "Is mahjong hard to learn? No — most beginners play a full game in one lesson.", "is mahjong hard, is mah jongg difficult", "Is Mahjong Hard?", "<p><strong>Is mahjong hard?</strong> Not with the right teachers. Most people play their first full game in one <a href=\"mahjong-101.html\">Mahjong 101</a> session. <a href=\"how-long-learn-mahjong.html\">How long to learn</a>.</p>", priority="0.91"),
    mahjong_kw("mahjong-four-players.html", "Four Players", "Mahjong four players — why American mah jongg needs exactly four.", "mahjong four players, 4 player mah jongg", "Mahjong — Four Players", "<p>American <strong>mahjong</strong> is a four-player game — one player per side of the table. Learn in <a href=\"mahjong-101.html\">Mahjong 101</a> with 4–8 guests (we rotate).</p>"),
    mahjong_kw("mahjong-party-cost.html", "Party Cost", "How much does a mahjong party cost? $125/person for Mahjong 101.", "mahjong party cost, how much mah jongg lesson", "Mahjong Party Cost", "<p><strong>Mahjong party cost:</strong> <a href=\"mahjong-101.html\">Mahjong 101</a> is $125/person · <a href=\"mahjong-102.html\">102</a> is $115/person. We bring tiles, tables, and cards. <a href=\"book-mahjong-lesson.html\">Book</a>.</p>", priority="0.89"),
    mahjong_kw("tournament-rules-mahjong.html", "Tournament Rules", "Mahjong tournament rules — etiquette and play for competitive events.", "mahjong tournament rules, tournament mah jongg etiquette", "Mahjong Tournament Rules", "<p><strong>Tournament rules</strong> and etiquette — prepare with <a href=\"mahjong-102.html\">Mahjong 102</a> · play at <a href=\"greenbrier-mahjong.html\">The Greenbrier</a> · <a href=\"mahjong-tournament.html\">tournaments</a>.</p>"),
    mahjong_kw("tml-ambassador-mahjong.html", "TML Ambassador", "TML Ambassador — certified The Mahjong Line instructors. Code LOOKOUTMOUNTAIN.", "tml ambassador, the mahjong line ambassador, mahjong line ambassador", "TML Ambassador Mahjong", "<p>Certified <strong>TML Ambassadors</strong> — <a href=\"mahj-jen-mahj-hen.html\">Mahj Jen &amp; Mahj Hen</a>. Shop tiles with code <strong>LOOKOUTMOUNTAIN</strong>. <a href=\"the-mahjong-line.html\">The Mahjong Line</a> · <a href=\"buy-mahjong-tiles.html\">Buy tiles</a>.</p>", priority="0.88"),
