    mahjong_kw("mahjong-concealed-hand.html", "Concealed Hand", "Concealed hand in mahjong — winning without exposing tiles.", "concealed hand mahjong, mah jongg concealed hand rules", "Concealed Hand", "<p>A <strong>concealed hand</strong> wins without exposing tiles on the table — often worth more points. Advanced topic in <a href=\"mahjong-102.html\">Mahjong 102</a>.</p>"),
