    mahjong_kw("retirement-community-mahjong.html", "Retirement Community", "Retirement community mahjong — active adult programming.", "retirement community mahjong, senior living mah jongg", "Retirement Community Mahjong", "<p>Retirement and active adult communities — bring <strong>mahjong</strong> programming to residents. <a href=\"mahjong-for-seniors.html\">For seniors</a> · <a href=\"senior-center-mahjong.html\">Senior center</a>.</p>"),
    mahjong_kw("country-club-brunch-mahjong.html", "Country Club Brunch", "Country club brunch mahjong — member programming with tiles.", "country club brunch mahjong, club brunch mah jongg", "Country Club Brunch Mahjong", "<p>Country clubs — pair member brunch with a <strong>mahjong</strong> lesson. <a href=\"country-club-mahjong.html\">Country club</a> · <a href=\"ladies-luncheon-mahjong.html\">Luncheon</a>.</p>"),
    mahjong_kw("mahjong-triples.html", "Triples Hands", "Triples in mahjong — three-of-a-kind hands on the NMJL card.", "triples mahjong, mah jongg triples hand", "Triples in Mahjong", "<p><strong>Triples</strong> hands require three of a kind — a core NMJL pattern. Learn to read them: <a href=\"read-nmjl-card.html\">Read the card</a> · <a href=\"mahjong-102.html\">102</a>.</p>"),
    mahjong_kw("even-numbers-mahjong.html", "Even Numbers Hands", "Even numbers in mahjong — 2468 category on the NMJL card.", "even numbers mahjong, 2468 mah jongg hand", "Even Numbers in Mahjong", "<p><strong>Even numbers</strong> (2468) is a popular NMJL category — pairs and sequences of evens. <a href=\"read-nmjl-card.html\">Read the card</a> · <a href=\"mahjong-hands.html\">Hands</a>.</p>"),
    mahjong_kw("odd-numbers-mahjong.html", "Odd Numbers Hands", "Odd numbers in mahjong — 13579 category on the NMJL card.", "odd numbers mahjong, 13579 mah jongg hand", "Odd Numbers in Mahjong", "<p><strong>Odd numbers</strong> (13579) hands use ones, threes, fives, sevens, and nines. <a href=\"read-nmjl-card.html\">Read the card</a> · <a href=\"mahjong-102.html\">102</a>.</p>"),
    mahjong_kw("369-mahjong.html", "369 Hands", "369 hands in mahjong — threes, sixes, and nines on the NMJL card.", "369 mahjong, 369 mah jongg hand category", "369 Hands in Mahjong", "<p>The <strong>369</strong> category uses threes, sixes, and nines across suits — a classic NMJL pattern. <a href=\"mahjong-hands.html\">Hands guide</a>.</p>"),
    mahjong_kw("stop-charleston-mahjong.html", "Stop the Charleston", "Stop the Charleston in mahjong — when a player stops tile passing.", "stop charleston mahjong, mah jongg stop charleston rules", "Stop the Charleston", "<p>Any player can <strong>stop the Charleston</strong> after the first left pass — ending the tile exchange early. Rules in <a href=\"mahjong-101.html\">Mahjong 101</a> · <a href=\"mahjong-charleston.html\">Charleston</a>.</p>"),
    mahjong_kw("pick-from-wall-mahjong.html", "Pick from the Wall", "Pick from the wall in mahjong — drawing tiles during play.", "pick from wall mahjong, mah jongg draw tile", "Pick from the Wall", "<p>Each turn you <strong>pick from the wall</strong> or claim a discard. Learn the full flow in <a href=\"mahjong-101.html\">Mahjong 101</a> · <a href=\"calling-mahjong.html\">Calling</a>.</p>"),
